function Tabzy(selector,options={}){this.container=document.querySelector(selector);if(!this.container){console.error(`Tabzy: No container found for selector ${selector}`);return}this.tabs=Array.from(this.container.querySelectorAll("li a"));if(!this.tabs.length){console.error(`Tabzy: No tabs found inside the container`);return}this.panels=this._getPanels();if(this.tabs.length!==this.panels.length){return}this.opt=Object.assign({remember:false,onChange:null},options);this._paramKey=this._escapeSpecialKeywords(selector);this._originalHTML=this.container.innerHTML;this._init()}Tabzy.prototype._getPanels=function(){return this.tabs.map(tab=>{const panel=document.querySelector(tab.getAttribute("href"));if(!panel){console.error("Tabzy: No panel found")}return panel}).filter(Boolean)};Tabzy.prototype._init=function(){const paramObj=new URLSearchParams(location.search);const tabSelector=paramObj.get(this._paramKey);const tab=this.opt.remember&&tabSelector&&this.tabs.find(tab=>this._escapeSpecialKeywords(tab.getAttribute("href"))===tabSelector)||this.tabs[0];this._activateTab(tab,false,false);this._currentTab=tab;this.tabs.forEach(tab=>{tab.onclick=event=>{event.preventDefault();this._tryActivateTab(tab)}})};Tabzy.prototype._activateTab=function(tab,triggerOnChange=true,updateURL=this.opt.remember){this.tabs.forEach(tab=>{tab.closest("li").classList.remove("tabzy--active")});tab.closest("li").classList.add("tabzy--active");this.panels.forEach(panel=>panel.hidden=true);const panelActive=document.querySelector(tab.getAttribute("href"));panelActive.hidden=false;if(updateURL){const paramObj=new URLSearchParams(location.search);paramObj.set(this._paramKey,this._escapeSpecialKeywords(tab.getAttribute("href")));history.replaceState(null,null,`?${paramObj}`)}if(triggerOnChange&&typeof this.opt.onChange==="function"){this.opt.onChange({tab:tab,panel:panelActive})}};Tabzy.prototype._escapeSpecialKeywords=function(input){if(typeof input!=="string"){console.error(`Tabzy: ${input} is not string type!`);return}return input.replace(/[^a-zA-Z0-9]/g,"")};Tabzy.prototype._tryActivateTab=function(tab){if(this._currentTab!==tab){this._currentTab=tab;this._activateTab(tab)}};Tabzy.prototype.switch=function(input){let tab=null;if(typeof input==="string"){tab=this.tabs.find(tab=>tab.getAttribute("href")===input);if(!tab){console.error(`Tabzy: No panel with ID ${input}`);return}}else if(this.tabs.includes(input)){tab=input}if(!tab){console.error(`Tabzy: Invalid input ${input}`);return}this._tryActivateTab(tab)};Tabzy.prototype.destroy=function(){this.container.innerHTML=this._originalHTML;this.panels.forEach(panel=>panel.hidden=false);this.container=null;this.tabs=null;this.panels=null;this._currentTab=null};